package com.bank.roster.service;

import com.bank.roster.model.Employee;
import java.util.List;
import java.util.logging.Logger;
import java.util.stream.Collectors;

public class RosterService {
    private static final Logger log = Logger.getLogger(RosterService.class.getName());

    public List<String> allNames(List<Employee> employees) {
        log.info(() -> "Extracting names from " + employees.size() + " employees");
        return employees.stream()
                .map(Employee::getName)   // Employee -> String, one-to-one
                .collect(Collectors.toList());
    }
}
