        List<Employee> staff = List.of(
            new Employee("Rajesh", "IT",    new BigDecimal("95000")),
            new Employee("Priya",  "Sales", new BigDecimal("72000")),
            new Employee("Amit",   "HR",    new BigDecimal("48000"))
        );

        List<String> names = new RosterService().allNames(staff);
